B.ay1=new A.cz("\u062d\u0631\u0643\u0627\u062a \u0623\u0642\u062f\u0645 \u0645\u0646 15 \u0634\u0647\u0631\u0627\u064b \u0645\u0646 \u0627\u0644\u0623\u0631\u0634\u064a\u0641 \u0641\u064a Google Drive. \u0631\u0635\u064a\u062f\u0647\u0627 \u0645\u062d\u0633\u0648\u0628 \u0636\u0645\u0646 \xab\u0631\u0635\u064a\u062f \u0645\u0631\u062d\u0651\u0644\xbb \u0641\u064a \u0643\u0634\u0641 \u0627\u0644\u062d\u0633\u0627\u0628.",null)
B.ay3=new A.cz("\u0645\u0627 \u0641\u064a \u0639\u0631\u0628\u0627\u062a \u0645\u062a\u0627\u062d\u0629. \u0623\u0636\u0641 \u0639\u0631\u0628\u064a\u0629 \u0645\u0646 \xab\u0627\u0644\u0639\u0631\u0628\u0627\u062a\xbb \u0623\u0648\u0644\u0627\u064b.",null)
